# Authored institutional statements (E) -- part 3: Chapters IV-V (Articles 22-29), final formula, Annexes I-V
from reg import *

# ---- Article 22
st('s_a22', ['A22.P0', 'A22.P0.pta', 'A22.P0.ptb', 'A22.P0.ptc'], 'assignment_bearing',
   'The Commission and the Member States concerned, commensurate to their responsibilities, foster synergies and ensure coordination between the Fund and the Union programmes and instruments referred to in Article 6(3) and the Modernisation Fund, ensuring complementarity, optimising coordination mechanisms and ensuring close cooperation between those responsible for implementation and control.',
   'The Commission and the Member States concerned shall, in a manner commensurate to their respective responsibilities, foster synergies and ensure effective coordination between the Fund and the Union programmes and instruments referred to in Article 6(3) of this Regulation')

# ---- Article 23
st('s_a23p1a', 'A23.P1', 'assignment_bearing',
   'Member States make the data referred to in Article 21(2)(d)(i), (ii) and (iv) publicly available and up to date on a single website in open, machine-readable formats.',
   'Member States shall make the data referred to in Article 21(2), point (d)(i), (ii) and (iv), of this Regulation publicly available and keep them up to date on a single website in open, machine-readable formats')
st('s_a23p1b', 'A23.P1', 'procedural',
   'Information under Article 21(2)(d)(i) and (ii) is not published in the cases of Article 38(3) of the Financial Regulation or for temporary direct income support to vulnerable households.',
   'shall not be published in the cases referred to in Article 38(3) of Regulation (EU, Euratom) 2018/1046 or in the case of temporary direct income support to vulnerable households')
st('s_a23p2a', 'A23.P2', 'assignment_bearing',
   'Recipients of support from the Fund are informed of the origin of the funds, including where they benefit through intermediaries; information includes the Union emblem and a funding statement.',
   'The recipients of support from the Fund shall be informed of the origin of those funds, including where they benefit from those funds through intermediaries')
st('s_a23p2b', 'A23.P2', 'assignment_bearing',
   'Recipients of support from the Fund, except for support to natural persons or where commercially sensitive information is at risk, ensure the visibility of Union funding, providing information to multiple audiences including the media and the public.',
   'The recipients of support from the Fund, except the support for natural persons or where there is risk of commercially sensitive information being made public, shall ensure the visibility of the Union funding')
st('s_a23p3a', 'A23.P3', 'assignment_bearing',
   'The Commission implements information and communication actions relating to the Fund, to actions under the Regulation and to results obtained.',
   'The Commission shall implement information and communication actions relating to the Fund, to actions taken pursuant to this Regulation and to the results obtained')
st('s_a23p3b', 'A23.P3', 'relation_bearing',
   'Where appropriate and with the agreement of the national authorities, the Commission carries out joint communication activities with national authorities and the representation offices of the European Parliament and of the Commission in the Member State concerned.',
   'through joint communication activities with the national authorities and the representation offices of the European Parliament and of the Commission in the Member State concerned')

# ---- Article 24
st('s_a24p1a', 'A24.P1', 'relation_bearing',
   'Each Member State reports to the Commission on a biennial basis on implementation of its Plan together with its integrated national energy and climate progress report under Regulation (EU) 2018/1999.',
   'Each Member State shall, on a biennial basis, report to the Commission on the implementation of its Plan together with its integrated national energy and climate progress report pursuant to Article 17 of Regulation (EU) 2018/1999 and in accordance with Article 28 thereof')
st('s_a24p1b', 'A24.P1', 'relation_bearing',
   'Member States include the Annex IV indicators in their progress report.',
   'The Member States shall include the indicators set out in Annex IV to this Regulation in their progress report')
st('s_a24p2', 'A24.P2', 'assignment_bearing',
   'The Commission monitors implementation of the Fund and measures achievement of its objectives.',
   'The Commission shall monitor the implementation of the Fund and measure the achievement of its objectives')
st('s_a24p3a', 'A24.P3', 'assignment_bearing',
   "The Commission's performance reporting system ensures that data for monitoring implementation and results are collected efficiently, effectively and in a timely manner.",
   'The performance reporting system of the Commission shall ensure that data for monitoring the implementation of the activities and results are collected efficiently, effectively and in a timely manner')
st('s_a24p3b', 'A24.P3', 'assignment_bearing',
   'Proportionate reporting requirements are imposed on recipients of support from the Fund.',
   'proportionate reporting requirements shall be imposed on recipients of support from the Fund')
st('s_a24p4', 'A24.P4', 'assignment_bearing',
   'The Commission uses the common indicators of Annex IV for reporting on progress and for monitoring and evaluation of the Fund towards the objectives of Article 3.',
   'The Commission shall use the common indicators set out in Annex IV for reporting on the progress and for the purpose of monitoring and evaluation of the Fund towards the achievement of the objectives set out in Article 3')

# ---- Article 25
st('s_a25p1', 'A25.P1', 'relation_bearing',
   'The Commission transmits the Plans submitted by Member States and the decisions, as made public by the Commission, simultaneously and on equal terms to the European Parliament and the Council without undue delay.',
   'The Commission shall transmit the Plans submitted by Member States and the decisions, as made public by the Commission, simultaneously and on equal terms to the European Parliament and the Council without undue delay')
st('s_a25p2', 'A25.P2', 'procedural',
   'Information transmitted by the Commission to the Council in the context of the Regulation is simultaneously made available to the European Parliament, subject to confidentiality arrangements if necessary.',
   'Information transmitted by the Commission to the Council in the context of this Regulation or its implementation shall simultaneously be made available to the European Parliament, subject to confidentiality arrangements if necessary')
st('s_a25p3', 'A25.P3', 'relation_bearing',
   'The competent committees of the European Parliament may invite the Commission to provide information on the state of play of the Commission assessment of the Plans.',
   'The competent committees of the European Parliament may invite the Commission to provide information on the state of play of the assessment by the Commission of the Plans')

# ---- Article 26
st('s_a26p1', ['A26.P1', 'A26.P1.pta', 'A26.P1.ptb', 'A26.P1.ptc', 'A26.P1.ptd'], 'relation_bearing',
   'To enhance dialogue between Union institutions and ensure greater transparency and accountability, the competent committees of the European Parliament may invite the Commission twice a year to discuss the Plans, the Commission assessment of the Plans, the status of achievement of milestones and targets, and payment, suspension and termination procedures.',
   'the competent committees of the European Parliament may invite the Commission twice a year to discuss the following matters:')
st('s_a26p2', 'A26.P2', 'relation_bearing',
   'The Commission takes account of any elements arising from the views expressed through the social climate dialogue, including resolutions of the European Parliament if provided.',
   'The Commission shall take account of any elements arising from the views expressed through the social climate dialogue, including the resolutions of the European Parliament if provided')

# ---- Article 27
st('s_a27p1a', 'A27.P1', 'relation_bearing',
   'Two years after the start of implementation of the Plans the Commission provides the European Parliament, the Council, the EESC and the Committee of the Regions with an evaluation report on implementation and functioning of the Fund, taking into account the first Member State reports under Article 24.',
   'the Commission shall provide the European Parliament, the Council, the European Economic and Social Committee and the Committee of the Regions with an evaluation report on the implementation and functioning of the Fund, taking into account the results of the first reports submitted by Member States in accordance with Article 24')
st('s_a27p1b', 'A27.P1', 'assignment_bearing',
   'The Commission submits, where appropriate, proposals for amendments to the Regulation.',
   'shall submit, where appropriate, any proposals for amendments to this Regulation')
st('s_a27p2', ['A27.P2', 'A27.P2.pta', 'A27.P2.ptb', 'A27.P2.ptc', 'A27.P2.ptd'], 'procedural',
   'The evaluation report assesses achievement of objectives, efficiency and Union added value, country-by-country efficiency, application of the energy poverty and transport poverty definitions, and continued relevance of objectives, measures and assigned revenues.',
   'The evaluation report referred to in paragraph 1 shall, in particular, assess:')
st('s_a27p3', 'A27.P3', 'relation_bearing',
   'By 31 December 2033 the Commission provides the European Parliament, the Council, the EESC and the Committee of the Regions with an independent ex post evaluation report with a global assessment of the Fund and its impact.',
   'the Commission shall provide the European Parliament, the Council, the European Economic and Social Committee and the Committee of the Regions with an independent ex post evaluation report')
st('s_a27p4', 'A27.P4', 'assignment_bearing',
   'If revenue from auctioning under Article 30d(5) of Directive 2003/87/EC is established as an own resource under Article 311(3) TFEU, the Commission presents, as appropriate, proposals ensuring effectiveness and continuity of implementation of the Fund within the post-2027 financial framework.',
   'the Commission shall, as appropriate, present the necessary proposals in order to ensure, within the framework of the multiannual financial framework post 2027, the effectiveness and continuity of the implementation of the Fund')

# ---- Article 28 (amendment of Regulation (EU) 2021/1060; GAP-02)
st('s_a28p0', 'A28.P0', 'external_referencing',
   'An Article 26a is inserted in Regulation (EU) 2021/1060 (amendment of another instrument).',
   'The following Article is inserted in Regulation (EU) 2021/1060')
st('s_a28i1', 'A28.INS26a.P1', 'procedural',
   'Resources transferred from the Social Climate Fund are implemented in accordance with Regulation (EU) 2021/1060 and the provisions governing the receiving Fund and are definitive.',
   'shall be implemented in accordance with this Regulation and the provisions governing the Fund to which the resources are transferred and shall be definitive')
st('s_a28i2a', 'A28.INS26a.P2', 'assignment_bearing',
   'Where Member States implement the transferred resources under shared management they submit programme amendments in accordance with Article 24 of Regulation (EU) 2021/1060.',
   'they shall submit programme amendments in accordance with Article 24 of this Regulation concerning one or more programmes')
st('s_a28i2b', 'A28.INS26a.P2', 'assignment_bearing',
   'Member States plan the use of the transferred resources for achieving the Union budget climate objectives under Article 6(1) of Regulation (EU) 2021/1060.',
   'Member States shall plan the use of such resources for achieving the climate objectives set out for the Union budget in accordance with Article 6(1) of this Regulation')
st('s_a28i3', 'A28.INS26a.P3', 'assignment_bearing',
   'Where the Commission has already approved a programme amendment relating to a transfer, the Member State may submit a notification of financial tables instead of an amendment for further transfers, if changes relate exclusively to an increase of financial resources.',
   'the Member State may submit a notification of financial tables instead of an amendment of a programme')
st('s_a28i4', ['A28.INS26a.P4', 'A28.INS26a.P5'], 'procedural',
   'Derogations: transferred resources are not taken into account for the mid-term review and flexibility amount; the decommitment time limit starts from the year of the budgetary commitments; resources shall not be transferred to Interreg programmes.',
   'Resources shall not be transferred to programmes under the European territorial cooperation goal (Interreg)')

# ---- Article 29 and final formula
st('s_a29p1', 'A29.P1', 'final_formal',
   'The Regulation enters into force on the twentieth day following its publication in the Official Journal.',
   'This Regulation shall enter into force on the twentieth day following that of its publication in the Official Journal of the European Union')
st('s_a29p2', 'A29.P2', 'final_formal',
   'The Regulation applies from 30 June 2024.',
   'It shall apply from 30 June 2024')
st('s_finbind', 'FIN.BIND', 'final_formal',
   'The Regulation is binding in its entirety and directly applicable in all Member States.',
   'This Regulation shall be binding in its entirety and directly applicable in all Member States')

