st('s_anx1', [f'ANX1.pt{i}' for i in range(1, 34)], 'procedural',
   'Annex I sets out the methodology (variables, formulae, adjustments) for calculating the maximum financial allocation of each Member State in accordance with Articles 10 and 14.',
   'This Annex sets out the methodology for calculating the maximum financial allocation available for each Member State in accordance with Articles 10 and 14')
